def selectSong():
    global openlink
    global song
    global songschosen
    global n
    limSongs=[]
    if optCountry.get()=="Country" and optYear.get()=="Contest" and optLanguage.get()=="Language":
        song=random.choice(songs)
    else:
        if optCountry.get()!="Country":
            reqC=optCountry.get()
            for i in songs:
                if i.split("|")[0]==reqC:
                    limSongs.append(i)
        if optYear.get()!="Contest":
            reqY=optYear.get()
            for i in songs:
                if i.split("|")[1]==reqY:
                    limSongs.append(i)
        if optLanguage.get()!="Language":
            reqL=optLanguage.get()
            for i in songs:
                if reqL in i.split("|")[4].split(",") or " "+reqL in i.split("|")[4].split(","):
                    limSongs.append(i)
        song=random.choice(limSongs)    
    songschosen.append(song)
    n=len(songschosen)-1
    song=song.split("|")
    country.config(text="Country: "+song[0])
    year.config(text="Contest: "+song[1])
    songt.config(text="Song: "+song[3])
    artist.config(text="Artist(s): "+song[2])
    lang.config(text="Language(s): "+song[4])
    position.config(text="Final Placement: "+song[5])
    root.update()
    if openlink:
        time.sleep(2)
        webbrowser.open(song[6])
def selectSong2(action):
    selectSong()
