def reset_dropdowns(changed_var):
    if changed_var=="country":
        optLanguage.set("Language")
        optYear.set("Contest")
    elif changed_var=="language":
        optCountry.set("Country")
        optYear.set("Contest")
    elif changed_var=="contest":
        optCountry.set("Country")
        optLanguage.set("Language")
    elif changed_var=="all":
        optCountry.set("Country")
        optYear.set("Contest")
        optLanguage.set("Language")
