optCountry=tk.StringVar(value="Country")
optLanguage=tk.StringVar(value="Language")
optYear=tk.StringVar(value="Contest")
dropdownC=tk.OptionMenu(root,optCountry,*eurovision_countries,command=lambda _:reset_dropdowns("country"))
dropdownY=tk.OptionMenu(root,optYear,*eurovision_years,command=lambda _:reset_dropdowns("contest"))
dropdownL=tk.OptionMenu(root,optLanguage,*eurovision_languages,command=lambda _:reset_dropdowns("language"))
dropdownC["menu"].config(fg="white",bg="grey17",activebackground="grey25",font=("Calibri",9))
dropdownY["menu"].config(fg="white",bg="grey17",activebackground="grey25",font=("Calibri",9))
dropdownL["menu"].config(fg="white",bg="grey17",activebackground="grey25",font=("Calibri",9))
