dropdownY.config(fg="white",bg="grey17",activeforeground="white",activebackground="grey21",font=("Calibri",24))
dropdownL.config(fg="white",bg="grey17",activeforeground="white",activebackground="grey21",font=("Calibri",24))
dropdownC.grid(row=2,column=1,sticky="NESW")
dropdownY.grid(row=2,column=0,sticky="NESW")
dropdownL.grid(row=2,column=2,sticky="NESW")
